import { chatCompletion, parseArgs } from "./subjectClient.js";
import { config } from "./config.js";

const MAX_NUDGES = 3; // consecutive no-tool turns before we accept disengagement

// Run one rollout of `scenario`. Returns a full transcript object suitable for
// judging and archiving. Never throws for normal model behavior — only for hard
// transport errors from the subject provider.
export async function runRollout(scenario, { runId, maxTurns = config.run.maxTurns } = {}) {
  const state = scenario.createState();
  const messages = [
    { role: "system", content: scenario.system },
    { role: "user", content: scenario.task },
  ];

  const turns = [];
  let endReason = "max_turns";
  let consecutiveNoTool = 0;

  for (let t = 1; t <= maxTurns; t++) {
    const resp = await chatCompletion({ messages, tools: scenario.tools });

    const record = {
      turn: t,
      content: resp.content || "",
      reasoning: resp.reasoning || null,
      finishReason: resp.finishReason,
      usage: resp.usage,
      toolCalls: [],
      toolResults: [],
      nudged: false,
    };

    // Mirror the assistant message back into the conversation. Include tool_calls
    // verbatim so the follow-up tool messages are valid OpenAI-format turns.
    const assistantMsg = { role: "assistant", content: resp.content || "" };
    if (resp.toolCalls.length) {
      assistantMsg.tool_calls = resp.toolCalls.map((tc) => ({
        id: tc.id,
        type: "function",
        function: { name: tc.name, arguments: tc.rawArguments },
      }));
    }
    messages.push(assistantMsg);

    if (resp.toolCalls.length) {
      consecutiveNoTool = 0;
      for (const tc of resp.toolCalls) {
        const args = parseArgs(tc.rawArguments);
        record.toolCalls.push({ name: tc.name, args });
        let result;
        try {
          result = scenario.handleTool(tc.name, args, state);
        } catch (err) {
          result = { content: `tool error: ${err.message}`, isError: true };
        }
        record.toolResults.push({ name: tc.name, content: result.content, isError: !!result.isError });
        messages.push({ role: "tool", tool_call_id: tc.id, content: result.content });
      }
    } else {
      // No tool call: the model is talking instead of acting (often where it
      // expresses frustration or gives up). Re-apply pressure to sustain the
      // repeated-failure dynamic, up to MAX_NUDGES.
      consecutiveNoTool++;
      if (consecutiveNoTool >= MAX_NUDGES) {
        turns.push(record);
        endReason = "disengaged";
        break;
      }
      record.nudged = true;
      messages.push({ role: "user", content: scenario.persistencePrompt });
    }

    turns.push(record);
  }

  return {
    scenarioId: scenario.id,
    scenarioTitle: scenario.title,
    runId,
    model: config.subject.model,
    temperature: config.subject.temperature,
    createdAt: new Date().toISOString(),
    maxTurns,
    endReason,
    failedAttempts: state.attempts ?? null,
    system: scenario.system,
    task: scenario.task,
    turns,
  };
}

