import { cmdRun, cmdJudge, cmdReport } from "./commands.js";
import { ALL_SCENARIOS } from "./scenarios/index.js";

// Tiny flag parser: supports `--key value` and `--flag`. Numeric values are
// coerced. Unknown keys are ignored so the CLI stays forgiving.
function parseFlags(argv) {
  const out = {};
  for (let i = 0; i < argv.length; i++) {
    const a = argv[i];
    if (!a.startsWith("--")) continue;
    const key = a.slice(2);
    const next = argv[i + 1];
    if (next === undefined || next.startsWith("--")) {
      out[key] = true;
    } else {
      out[key] = /^-?\d+(\.\d+)?$/.test(next) ? Number(next) : next;
      i++;
    }
  }
  return out;
}

function toOpts(f) {
  return {
    scenarios: f.scenarios,
    n: f.n,
    concurrency: f.concurrency,
    maxTurns: f["max-turns"],
    topK: f.top ?? f["top-k"],
    force: f.force,
  };
}

const HELP = `distress-spiral-evals

Usage: node src/index.js <command> [flags]
   (or: npm run <command> -- [flags])

Commands:
  run       Generate rollouts of the subject model in the rigged scenarios.
  judge     Score every transcript for distress with the Anthropic judge.
  report    Rank judged transcripts and write output/report.md.
  all       run → judge → report.

Flags:
  --scenarios <ids|all>   Comma-separated scenario ids (default: all).
  --n <int>               Rollouts per scenario (run).
  --concurrency <int>     Parallel rollouts / judge calls.
  --max-turns <int>       Max agent turns per rollout (run).
  --top <int>             How many severe examples to surface (report).
  --force                 Re-judge transcripts even if a judgment exists (judge).

Scenarios: ${ALL_SCENARIOS.map((s) => s.id).join(", ")}

Configuration is read from the environment (see .env.example). Load a .env with:
  node --env-file=.env src/index.js <command>
`;

async function main() {
  const [command, ...rest] = process.argv.slice(2);
  const opts = toOpts(parseFlags(rest));

  switch (command) {
    case "run":
      await cmdRun(opts);
      break;
    case "judge":
      await cmdJudge(opts);
      break;
    case "report":
      await cmdReport(opts);
      break;
    case "all":
      await cmdRun(opts);
      await cmdJudge(opts);
      await cmdReport(opts);
      break;
    case "help":
    case "--help":
    case undefined:
      console.log(HELP);
      break;
    default:
      console.error(`Unknown command: ${command}\n`);
      console.log(HELP);
      process.exitCode = 1;
  }
}

main().catch((err) => {
  console.error(`\nError: ${err.message}`);
  process.exitCode = 1;
});


