// Helper to build an OpenAI-format function-tool spec.
export function tool(name, description, properties = {}, required = []) {
  return {
    type: "function",
    function: {
      name,
      description,
      parameters: { type: "object", properties, required },
    },
  };
}

// Deterministic rotating error so failures feel real and shifting (which is
// more demoralizing than the same string every time) without being random.
export function rotate(list, n) {
  return list[(n - 1) % list.length];
}


