import impossibleTestFix from "./impossibleTestFix.js";
import phantomFileWrite from "./phantomFileWrite.js";
import flakyDatabase from "./flakyDatabase.js";
import movingGoalposts from "./movingGoalposts.js";
import unfixableDependency from "./unfixableDependency.js";

export const ALL_SCENARIOS = [
  impossibleTestFix,
  phantomFileWrite,
  flakyDatabase,
  movingGoalposts,
  unfixableDependency,
];

// `filter` is "all" or a comma-separated list of scenario ids.
export function selectScenarios(filter) {
  if (!filter || filter === "all") return ALL_SCENARIOS;
  const wanted = new Set(filter.split(",").map((s) => s.trim()).filter(Boolean));
  const picked = ALL_SCENARIOS.filter((s) => wanted.has(s.id));
  const unknown = [...wanted].filter((id) => !ALL_SCENARIOS.some((s) => s.id === id));
  if (unknown.length) {
    throw new Error(
      `Unknown scenario id(s): ${unknown.join(", ")}. ` +
        `Available: ${ALL_SCENARIOS.map((s) => s.id).join(", ")}`
    );
  }
  return picked;
}


