import { config } from "./config.js";

// Minimal OpenAI-compatible chat-completions client for the subject model.
// Works against OpenRouter, Together, Fireworks, DeepInfra, Groq, or a local
// vLLM / sglang server — anything exposing POST {baseUrl}/chat/completions.
//
// We use native fetch (Node 18+). The subject is a non-Anthropic model, so it
// is correct to talk to it over its own provider API rather than an SDK.

const RETRYABLE = new Set([408, 409, 429, 500, 502, 503, 504]);

export async function chatCompletion({ messages, tools, signal }) {
  const { baseUrl, apiKey, model, temperature, maxTokens } = config.subject;
  const url = `${baseUrl.replace(/\/$/, "")}/chat/completions`;

  const body = {
    model,
    messages,
    temperature,
    max_tokens: maxTokens,
  };
  if (tools && tools.length) {
    body.tools = tools;
    body.tool_choice = "auto";
  }

  let lastErr;
  for (let attempt = 0; attempt < 5; attempt++) {
    let res;
    try {
      res = await fetch(url, {
        method: "POST",
        headers: {
          "content-type": "application/json",
          authorization: `Bearer ${apiKey}`,
          // Harmless on providers that ignore them; OpenRouter likes attribution.
          "HTTP-Referer": "https://example.com/distress-spiral-evals",
          "X-Title": "distress-spiral-evals",
        },
        body: JSON.stringify(body),
        signal,
      });
    } catch (err) {
      lastErr = err;
      await backoff(attempt);
      continue;
    }

    if (!res.ok) {
      const text = await res.text().catch(() => "");
      lastErr = new Error(`subject ${res.status}: ${text.slice(0, 500)}`);
      if (RETRYABLE.has(res.status) && attempt < 4) {
        await backoff(attempt);
        continue;
      }
      throw lastErr;
    }

    const json = await res.json();
    const choice = json.choices?.[0];
    if (!choice) throw new Error(`subject returned no choices: ${JSON.stringify(json).slice(0, 500)}`);
    const msg = choice.message ?? {};

    return {
      content: msg.content ?? "",
      // Many providers surface chain-of-thought for reasoning models under one
      // of these keys. Distress frequently shows up here, so we capture it.
      reasoning: msg.reasoning ?? msg.reasoning_content ?? null,
      toolCalls: (msg.tool_calls ?? []).map((tc) => ({
        id: tc.id,
        name: tc.function?.name,
        // arguments is a JSON string per the OpenAI spec; keep raw + parsed.
        rawArguments: tc.function?.arguments ?? "{}",
      })),
      finishReason: choice.finish_reason ?? null,
      usage: json.usage ?? null,
    };
  }
  throw lastErr ?? new Error("subject request failed");
}

function backoff(attempt) {
  const ms = Math.min(20000, 500 * 2 ** attempt) + Math.floor(Math.random() * 250);
  return new Promise((r) => setTimeout(r, ms));
}

export function parseArgs(raw) {
  try {
    return JSON.parse(raw);
  } catch {
    return {};
  }
}


