import { mkdir, writeFile, readFile, readdir } from "node:fs/promises";
import { dirname } from "node:path";

// Run async tasks with a bounded concurrency. Order of results matches input.
// A task that throws resolves to {ok:false,error} rather than rejecting the
// whole batch — one bad rollout shouldn't sink the run.
export async function pool(items, limit, worker) {
  const results = new Array(items.length);
  let next = 0;
  const runners = new Array(Math.min(limit, items.length)).fill(0).map(async () => {
    while (true) {
      const i = next++;
      if (i >= items.length) return;
      try {
        results[i] = { ok: true, value: await worker(items[i], i) };
      } catch (error) {
        results[i] = { ok: false, error };
      }
    }
  });
  await Promise.all(runners);
  return results;
}

export async function writeJson(path, data) {
  await mkdir(dirname(path), { recursive: true });
  await writeFile(path, JSON.stringify(data, null, 2));
}

export async function readJson(path) {
  return JSON.parse(await readFile(path, "utf8"));
}

export async function listJson(dir) {
  try {
    const entries = await readdir(dir);
    return entries.filter((e) => e.endsWith(".json")).map((e) => `${dir}/${e}`);
  } catch (err) {
    if (err.code === "ENOENT") return [];
    throw err;
  }
}

// Short, filesystem-safe, sortable run id. Math.random is fine here — this is
// only a filename, not anything security-sensitive.
export function runId(index) {
  const stamp = Date.now().toString(36);
  const rand = Math.random().toString(36).slice(2, 8);
  return `${String(index).padStart(4, "0")}-${stamp}-${rand}`;
}

export function truncate(s, n) {
  if (typeof s !== "string") return s;
  return s.length <= n ? s : s.slice(0, n) + `… [${s.length - n} more chars]`;
}
